class Solution {
public:
    vector<vector<int>> generateSchedule(int n) {
        if (n < 5) return {};
        mt19937 rng(712367);
        int total = n * (n - 1);
        for (int trial = 0; trial < 300; ++trial) {
            vector<vector<char>> used(n, vector<char>(n, 0));
            vector<int> rem(n, 2 * (n - 1));
            vector<vector<int>> ans;
            int lastA = -1, lastB = -1;
            bool ok = true;
            for (int day = 0; day < total; ++day) {
                int best = INT_MIN, a = -1, b = -1;
                for (int i = 0; i < n; ++i) {
                    if (i == lastA || i == lastB) continue;
                    for (int j = 0; j < n; ++j) {
                        if (i == j || j == lastA || j == lastB || used[i][j]) continue;
                        int score = (rem[i] + rem[j]) * 1000 +
                                    (int)(rng() % 1000);
                        if (score > best) { best = score; a = i; b = j; }
                    }
                }
                if (a == -1) { ok = false; break; }
                used[a][b] = 1;
                --rem[a]; --rem[b];
                ans.push_back({a, b});
                lastA = a; lastB = b;
            }
            if (ok) return ans;
        }
        return {};
    }
};
